1	/**
2	 * Stripe webhook receiver (Phase 3).
3	 *
4	 * Local invoice state is fully driven by Stripe events. We never optimistically
5	 * mark a row paid from the UI — every status flip lands here through a signed
6	 * Stripe POST. The only escape hatch is `markInvoicePaidManually` for cash/wire.
7	 *
8	 * Events handled:
9	 *   invoice.paid           → status='paid',   paid_at=now()   (+ client receipt email)
10	 *   invoice.payment_failed → status='failed'                  (+ admin notification email)
11	 *   invoice.finalized      → mirror hosted_invoice_url        (re-finalization can change it)
12	 *   invoice.voided         → status='void'
13	 *
14	 * Everything else is acked with `200 { received: true, ignored }` so Stripe
15	 * stops retrying — Stripe expects 2xx for "received and acknowledged", not
16	 * "acted on".
17	 *
18	 * Idempotency: webhook delivery is at-least-once. We dedupe per `event.id`
19	 * with a small in-memory LRU (good enough for serverless single-region) AND
20	 * the underlying UPDATE is naturally idempotent (mirror-of-target-state).
21	 *
22	 * Runtime constraint: nodejs (Stripe SDK does not run on edge).
23	 */
24	import { NextResponse } from "next/server";
25	import { createAdminClient } from "@/lib/supabase/server";
26	import { verifyWebhookSignature } from "@/lib/stripe";
27	import { forgetStripeEvent, rememberStripeEvent } from "@/lib/stripe-event-dedupe";
28	import { sendEmail } from "@/lib/resend";
29	import {
30	  invoicePaidToClient,
31	  invoicePaymentFailedToAdmin
32	} from "@/lib/resend-templates";
33	import type Stripe from "stripe";
34	
35	export const runtime = "nodejs";
36	export const dynamic = "force-dynamic";
37	
38	const ADMIN_NOTIFY_TO = (): string =>
39	  process.env.RESEND_REPLY_TO ?? "jeremyw@dobeu.net";
40	
41	interface InvoiceRow {
42	  id: string;
43	  project_id: string;
44	  amount_cents: number;
45	  currency: string | null;
46	  status: string;
47	}
48	
49	export async function POST(request: Request): Promise<NextResponse> {
50	  const startedAt = Date.now();
51	  const requestId = request.headers.get("stripe-request-id") ?? crypto.randomUUID();
52	
53	  console.log(
54	    JSON.stringify({
55	      msg: "stripe_webhook_received",
56	      request_id: requestId,
57	      ts: new Date().toISOString()
58	    })
59	  );
60	
61	  const rawBody = await request.text();
62	  const sig = request.headers.get("stripe-signature");
63	
64	  let event: Stripe.Event;
65	  try {
66	    event = verifyWebhookSignature(rawBody, sig);
67	  } catch (e) {
68	    console.warn(
69	      JSON.stringify({
70	        msg: "stripe_webhook_invalid_signature",
71	        request_id: requestId,
72	        error: e instanceof Error ? e.message : String(e)
73	      })
74	    );
75	    return NextResponse.json({ ok: false, error: "invalid_signature" }, { status: 400 });
76	  }
77	
78	  if (rememberStripeEvent(event.id)) {
79	    console.log(
80	      JSON.stringify({
81	        msg: "stripe_webhook_duplicate",
82	        request_id: requestId,
83	        event_id: event.id,
84	        event_type: event.type
85	      })
86	    );
87	    return NextResponse.json({ received: true, deduped: true });
88	  }
89	
90	  console.log(
91	    JSON.stringify({
92	      msg: "stripe_webhook_verified",
93	      request_id: requestId,
94	      event_id: event.id,
95	      event_type: event.type
96	    })
97	  );
98	
99	  const admin = createAdminClient();
100	
101	  try {
102	    switch (event.type) {
103	      case "invoice.paid": {
104	        // The .neq("status","paid") guard makes this idempotent across
105	        // instances: the in-memory event dedupe (lib/stripe-event-dedupe.ts)
106	        // only protects a single instance, and Stripe delivers at-least-once.
107	        // A repeat delivery of an already-paid invoice now matches 0 rows ->
108	        // row is null -> notifyInvoicePaid no-ops, instead of re-sending the
109	        // "paid" receipt email on every redelivery.
110	        const inv = event.data.object as Stripe.Invoice;
111	        if (inv.id) {
112	          const { data: row } = await admin
113	            .from("invoices")
114	            .update({ status: "paid", paid_at: new Date().toISOString() })
115	            .eq("stripe_invoice_id", inv.id)
116	            .neq("status", "paid")
117	            .select("id,project_id,amount_cents,currency,status")
118	            .single();
119	
120	          await notifyInvoicePaid(admin, inv, row as InvoiceRow | null);
121	        }
122	        break;
123	      }
124	
125	      case "invoice.payment_failed": {
126	        // Schema enum (invoice_status) doesn't have 'failed'/'uncollectible'
127	        // -- 'overdue' is the closest semantic match (invoice didn't get
128	        // paid). The admin email is the operational signal; the local row's
129	        // status just keeps the dashboard honest. Same idempotency guard as
130	        // invoice.paid above -- a repeat delivery of an already-overdue
131	        // invoice no-ops instead of re-sending the admin alert.
132	        const inv = event.data.object as Stripe.Invoice;
133	        if (inv.id) {
134	          const { data: row } = await admin
135	            .from("invoices")
136	            .update({ status: "overdue" })
137	            .eq("stripe_invoice_id", inv.id)
138	            .neq("status", "overdue")
139	            .select("id,project_id,amount_cents,currency,status")
140	            .single();
141	
142	          await notifyInvoiceFailed(inv, row as InvoiceRow | null);
143	        }
144	        break;
145	      }
146	
147	      case "invoice.finalized": {
148	        const inv = event.data.object as Stripe.Invoice;
149	        if (inv.id && inv.hosted_invoice_url) {
150	          await admin
151	            .from("invoices")
152	            .update({ hosted_invoice_url: inv.hosted_invoice_url })
153	            .eq("stripe_invoice_id", inv.id);
154	        }
155	        break;
156	      }
157	
158	      case "invoice.voided": {
159	        const inv = event.data.object as Stripe.Invoice;
160	        if (inv.id) {
161	          await admin
162	            .from("invoices")
163	            .update({ status: "void" })
164	            .eq("stripe_invoice_id", inv.id);
165	        }
166	        break;
167	      }
168	
169	      default:
170	        console.log(
171	          JSON.stringify({
172	            msg: "stripe_webhook_ignored",
173	            request_id: requestId,
174	            event_id: event.id,
175	            event_type: event.type
176	          })
177	        );
178	        break;
179	    }
180	  } catch (e) {
181	    console.error(
182	      JSON.stringify({
183	        msg: "stripe_webhook_handler_error",
184	        request_id: requestId,
185	        event_id: event.id,
186	        event_type: event.type,
187	        error: e instanceof Error ? e.message : String(e)
188	      })
189	    );
190	    // Removing the event from the dedupe set lets Stripe retry. Errors are
191	    // worth retrying (transient DB, transient Resend) far more often than
192	    // they aren't.
193	    forgetStripeEvent(event.id);
194	    return NextResponse.json({ ok: false, error: "handler_error" }, { status: 500 });
195	  }
196	
197	  console.log(
198	    JSON.stringify({
199	      msg: "stripe_webhook_complete",
200	      request_id: requestId,
201	      event_id: event.id,
202	      event_type: event.type,
203	      duration_ms: Date.now() - startedAt
204	    })
205	  );
206	
207	  return NextResponse.json({ received: true });
208	}
209	
210	async function notifyInvoicePaid(
211	  admin: ReturnType<typeof createAdminClient>,
212	  stripeInv: Stripe.Invoice,
213	  row: InvoiceRow | null
214	): Promise<void> {
215	  if (!row) return;
216	  const recipient = stripeInv.customer_email ?? null;
217	  if (!recipient) return;
218	  try {
219	    const tpl = invoicePaidToClient({
220	      invoice: {
221	        id: row.id,
222	        amount_cents: row.amount_cents,
223	        currency: row.currency ?? "USD"
224	      },
225	      description: stripeInv.description ?? null
226	    });
227	    await sendEmail({ to: recipient, subject: tpl.subject, text: tpl.text, html: tpl.html });
228	  } catch (e) {
229	    console.warn("[stripe webhook] invoice.paid email failed (non-fatal):", e);
230	  }
231	  void admin; // reserved for future per-project owner lookup
232	}
233	
234	async function notifyInvoiceFailed(
235	  stripeInv: Stripe.Invoice,
236	  row: InvoiceRow | null
237	): Promise<void> {
238	  try {
239	    const tpl = invoicePaymentFailedToAdmin({
240	      invoice: row
241	        ? {
242	            id: row.id,
243	            amount_cents: row.amount_cents,
244	            currency: row.currency ?? "USD"
245	          }
246	        : {
247	            id: stripeInv.id ?? "(no local row)",
248	            amount_cents: stripeInv.amount_due ?? 0,
249	            currency: (stripeInv.currency ?? "usd").toUpperCase()
250	          },
251	      stripeInvoiceId: stripeInv.id ?? null
252	    });
253	    await sendEmail({
254	      to: ADMIN_NOTIFY_TO(),
255	      subject: tpl.subject,
256	      text: tpl.text,
257	      html: tpl.html
258	    });
259	  } catch (e) {
260	    console.warn("[stripe webhook] invoice.payment_failed email failed (non-fatal):", e);
261	  }
262	}
263

1	"use server";
2	/**
3	 * Work-order server actions (Phase 3 — fully wired).
4	 *
5	 * Per PRODUCTION-PLAN §7.4. State machine (enforced in code via TRANSITIONS):
6	 *   open → quoted → accepted → in_progress → delivered → closed
7	 *     └──────┴──────────┴───────────┴────────────┴──→ cancelled
8	 * `closed` and `cancelled` are terminal. `cancelled` is reachable from any
9	 * non-terminal state. Both `quoteWorkOrder` and `updateWorkOrderStatus`
10	 * read current status first and reject illegal transitions.
11	 *
12	 * Notifications go through `lib/resend.ts` + `lib/resend-templates.ts`. Every
13	 * email send is wrapped so a Resend / DKIM failure cannot break the underlying
14	 * action (work order still progresses).
15	 *
16	 * Invoice model (LOCKED): accepting a quote ONLY flips the work order to
17	 * `accepted` (+ `accepted_at`). The Stripe invoice is created later by the
18	 * ADMIN via the "Create Stripe Invoice" button (→ `createInvoiceForWorkOrder`
19	 * in lib/actions/invoices.ts). There is intentionally no auto-invoice on
20	 * accept — `work_orders.project_id` was never set client-side, so that branch
21	 * was dead anyway.
22	 *
23	 * Attachment uploads are a two-step signed-URL flow:
24	 *   1. `submitWorkOrder` validates size + MIME, inserts the work order, and
25	 *      mints a signed upload URL per attachment (no row inserted yet).
26	 *   2. The client PUTs the bytes, then calls `finalizeWorkOrderAttachment`
27	 *      which inserts the `work_order_attachments` row pointing at the real
28	 *      object. Row-after-bytes means a failed PUT never leaves a dangling
29	 *      attachment row whose signed-download link 404s.
30	 */
31	import { revalidatePath } from "next/cache";
