465	export async function updateWorkOrderStatus(
466	  raw: unknown
467	): Promise<ActionResult<{ id: string; status: WorkOrderStatus }>> {
468	  const parsed = updateStatusInput.safeParse(raw);
469	  if (!parsed.success) {
470	    return { ok: false, error: parsed.error.issues.map((i) => i.message).join("; ") };
471	  }
472	  const { id, status } = parsed.data;
473	
474	  let admin;
475	  try {
476	    ({ admin } = await requireAdmin());
477	  } catch (e) {
478	    if (e instanceof AuthError) return { ok: false, error: e.code };
479	    throw e;
480	  }
481	
482	  // Read current status and enforce the transition (the Zod enum only checks
483	  // the target is a valid status, not that open→...→target is legal).
484	  const { data: current, error: readErr } = await admin
485	    .from("work_orders")
486	    .select("status")
487	    .eq("id", id)
488	    .single();
489	  if (readErr || !current) return { ok: false, error: readErr?.message ?? "work order not found" };
490	  if (!canTransition(current.status as WorkOrderStatus, status)) {
491	    return { ok: false, error: `illegal transition "${current.status}" → "${status}"` };
492	  }
493	
494	  // Stamp the per-status timestamp so the client timeline can render it.
495	  const now = new Date().toISOString();
496	  const stamp: Record<string, string> = { status };
497	  if (status === "in_progress") stamp.in_progress_at = now;
498	  else if (status === "delivered") stamp.delivered_at = now;
499	  else if (status === "closed") stamp.closed_at = now;
500	  else if (status === "cancelled") stamp.cancelled_at = now;
501	
502	  const { data, error } = await admin
503	    .from("work_orders")
504	    // Cast: the `*_at` columns land in lib/database.types.ts via the central
505	    // `pnpm db:types` regen (migration 20260618000000); stale types until then.
506	    // eslint-disable-next-line @typescript-eslint/no-explicit-any
507	    .update(stamp as any)
508	    .eq("id", id)
509	    .select("id,title,service_type,created_by")
510	    .single();
511	
512	  if (error || !data) return { ok: false, error: error?.message ?? "update failed" };
513	
514	  // Email the owner about the status change (in_progress/delivered/closed/cancelled).
515	  try {
516	    const recipient = await resolveOwnerEmail(admin, data.created_by);
517	    if (recipient) {
518	      const tpl = workOrderStatusChangedToClient({
519	        workOrder: { id: data.id, title: data.title, service_type: data.service_type },
520	        newStatus: status
521	      });
522	      await sendEmail({
523	        to: recipient,
524	        subject: tpl.subject,
525	        text: tpl.text,
526	        html: tpl.html
527	      });
528	    }
529	  } catch (e) {
530	    console.warn("[updateWorkOrderStatus] client email failed (non-fatal):", e);
531	  }
532	
533	  revalidatePath("/admin/tickets");
534	  revalidatePath("/portal/tickets");
535	  return { ok: true, data: { id, status } };
536	}
