538	/**
539	 * Resolve a work-order owner's email via service-role admin client.
540	 * Returns null (don't throw) on lookup failure so emails stay non-fatal.
541	 */
542	async function resolveOwnerEmail(
543	  admin: { auth: { admin: { getUserById: (id: string) => Promise<{ data: { user: { email?: string | null } | null } | null }> } } },
544	  userId: string
545	): Promise<string | null> {
546	  try {
547	    const { data } = await admin.auth.admin.getUserById(userId);
548	    return data?.user?.email ?? null;
549	  } catch (e) {
550	    console.warn("[resolveOwnerEmail] lookup failed:", e);
551	    return null;
552	  }
553	}
