21	/**
22	 * Resolve the current authed user via the cookie-bound client.
23	 * Returns `{ user, supabase }`. Throws `AuthError` if no user.
24	 */
25	export async function requireUser(): Promise<{ user: User; supabase: DBClient }> {
26	  const supabase = (await createClient()) as DBClient;
27	  const {
28	    data: { user }
29	  } = await supabase.auth.getUser();
30	  if (!user) {
31	    throw new AuthError("not_authenticated");
32	  }
33	  return { user, supabase };
34	}
