53	/**
54	 * Custom error used by server-action guards. Client-action call sites convert
55	 * these to `{ error }` return values; admin pages will surface them as 403/redirect.
56	 */
57	export class AuthError extends Error {
58	  readonly code: "not_authenticated" | "forbidden";
59	  constructor(code: "not_authenticated" | "forbidden") {
60	    super(code);
61	    this.code = code;
62	    this.name = "AuthError";
63	  }
64	}
