1	import { type NextRequest, NextResponse } from "next/server";
2	import { updateSession } from "@/lib/supabase/middleware";
3	
4	// Vercel Services does not support Edge Function outputs. Prefer Node middleware.
5	// (Default Next.js middleware is Edge; Services rejects that as "middleware" Edge output.)
6	export const runtime = "nodejs";
7	
8	export async function middleware(request: NextRequest) {
9	  // Skew Protection: propagate the __vdpl deployment cookie on every response
10	  // so Next.js can detect version mismatch between client bundles and the server.
11	  // On Vercel this is handled automatically; this header ensures the cookie is
12	  // forwarded even through edge caching layers.
13	  const response = await updateSession(request);
14	
15	  // Pass through the skew-protection deployment cookie if Vercel injected it.
16	  const skewCookie = request.cookies.get("__vdpl");
17	  if (skewCookie) {
18	    (response as NextResponse).cookies.set("__vdpl", skewCookie.value, {
19	      httpOnly: true,
20	      sameSite: "strict",
21	      secure: true,
22	      path: "/",
23	    });
24	  }
25	
26	  return response;
27	}
28	
29	export const config = {
30	  matcher: [
31	    /*
32	     * Match all request paths except:
33	     * - _next/static (static files)
34	     * - _next/image (image optimization files)
35	     * - favicon.ico, sitemap.xml, robots.txt
36	     * - image files
37	     * - /oci (Vercel container service — routed outside the Next.js web service)
38	     */
39	    "/((?!_next/static|_next/image|favicon.ico|sitemap.xml|robots.txt|oci(?:/|$)|.*\\.(?:svg|png|jpg|jpeg|gif|webp|ico)$).*)",
40	  ],
41	};
